TYPE emp_cur_t IS REF CURSOR RETURN employees%ROWTYPE;
v_cur emp_cur_t;
OPEN v_cur FOR SELECT department_id, department_name FROM departments; -- 구조가 다름

v_cur SYS_REFCURSOR;
OPEN v_cur FOR SELECT * FROM departments;
-- 나중에
OPEN v_cur FOR SELECT * FROM employees; -- 완전히 다른 쿼리

CREATE FUNCTION get_employees(p_dept_id NUMBER) RETURN SYS_REFCURSOR IS
    v_cur SYS_REFCURSOR;
BEGIN
    OPEN v_cur FOR SELECT * FROM employees WHERE department_id = p_dept_id;
    RETURN v_cur;
END;

v_cur SYS_REFCURSOR;
OPEN v_cur FOR SELECT * FROM departments;
-- CLOSE 없이 바로
OPEN v_cur FOR SELECT * FROM employees;
